#!/bin/bash
# 2026-10-21: horizon-fix versions (author's go: "do the 3"; ERRATUM_PREDICTION_HORIZON_2026-10-21). Same ephemerides (dry runs reproduced
# T0, P and their errors exactly; overlapping rows identical); only the listing horizon changes.
cd /Users/fernando/Desktop/NASA
.venv/bin/python -I scripts/prereg_v2.py 162304222 --freeze --clock --version 4 --reason "v3 stopped at 2026-12-31 because of the wrong end-date constant in prereg_v2.py (JD 2461406.5 = 2027-01-01): S112 after that date, S113 and S114 had no predictions. v4 has the identical ephemeris (T0, P and errors reproduced exactly) and lists through 2027; the 68 rows shared with v3 are identical. v3 and its hash stay on record; S111 is scored from v3 unchanged, S112-S114 from v4." --desc "See ERRATUM_PREDICTION_HORIZON_2026-10-21." > logs/prereg_freeze_162304222_v4.log 2>&1; echo "162304222 v4 exit $?"
.venv/bin/python -I scripts/prereg_v2.py 53825235 --freeze --version 3 --reason "v2 listed no future predictions (generator capped at 399 epochs; last epoch 2025-08-23). The v3 that DECISIONS 68 required was never made. v3 has the identical ephemeris (reproduced exactly). S108 and the first part of S109 were observed before this freeze and are labelled retrodictions; the authors have not examined any S106+ data of this star (the generator refuses them), but these epochs are not prospective. S109 after the freeze and S110 are predictions." --desc "See ERRATUM_PREDICTION_HORIZON_2026-10-21." > logs/prereg_freeze_53825235_v3.log 2>&1; echo "53825235 v3 exit $?"
.venv/bin/python -I scripts/prereg_v2.py 3367979 --freeze --version 3 --reason "v2's list stopped at epoch 822 (2027-08-28; generator capped at 399 epochs). v3 has the identical ephemeris (reproduced exactly) and lists through 2027; the 399 rows shared with v2 are identical. v2 and its hash stay on record." --desc "See ERRATUM_PREDICTION_HORIZON_2026-10-21." > logs/prereg_freeze_3367979_v3.log 2>&1; echo "3367979 v3 exit $?"
# 2026-10-21 (re-check R1): v3 above omitted --ground, so its rows read "undated (future sectors [])" and its text kept the TESS clauses.
# v4 is the ground registration: same ephemeris; all 399 rows shared with v2 identical in every field; precision derived from the depth.
.venv/bin/python -I scripts/prereg_v2.py 3367979 --freeze --ground --ground-mmag 0.6 --version 4 --reason "v3 (2026-10-21) extended v2's list (capped at epoch 822) but was generated without --ground: its sector labels read 'undated (future sectors [])' and its text kept the TESS-sector outcome clauses although this star has no TESS coverage through Sector 134. v4 is generated with --ground: identical ephemeris, all 399 rows shared with v2 identical in every field, list through 2027. v2 and v3 stay on record; v3 is superseded and is not a test of record." --desc "Ground precision: the required <= 0.6 mmag per 10-min bin is the precision at which one transit at the reference depth (788 ppm, T14 1.30 h, about 7.8 bins) reaches SNR 4 (1.0857 x 0.000788 x sqrt(7.8) / 4 = 0.60 mmag); the generic 1.5-mmag template value would make the per-epoch SNR >= 4 requirement unreachable. This object is a credited eumemic rediscovery with a marginal stellar density; it is not claimed as a new candidate. See ERRATUM_PREDICTION_HORIZON_2026-10-21." > logs/prereg_freeze_3367979_v4.log 2>&1; echo "3367979 v4 exit $?"
